from pathlib import Path
p=Path('leaderboards.js')
s=p.read_text(encoding='utf-8')

def one(old,new,label):
    global s
    c=s.count(old)
    if c!=1: raise SystemExit(f'{label}: expected 1 match, got {c}')
    s=s.replace(old,new,1)

one("function demoRows(view,anchor){if(view==='daily30')return demoDay(anchor);const t=today();let ds=view==='week'?between(anchor,addDays(anchor,6)).filter(d=>d<=t):view==='month'?Array.from({length:dim(anchor.slice(0,7))},(_,i)=>anchor.slice(0,7)+'-'+String(i+1).padStart(2,'0')).filter(d=>d<=t&&d>=START):between(START,t),m=new Map();ds.forEach(d=>demoDay(d).forEach(x=>{const c=m.get(x.id)||{id:x.id,name:x.name,score:0,durationSeconds:0,played:0,isPlayer:false};c.score+=x.score;c.durationSeconds+=x.durationSeconds;c.played++;m.set(x.id,c)}));return[...m.values()]}",
"function demoRows(view,anchor){if(view==='daily30')return demoDay(anchor);const from=view==='week'?weekStart(anchor):view==='month'?monthStart(anchor):START,ds=between(from,anchor),m=new Map();ds.forEach(d=>demoDay(d).forEach(x=>{const c=m.get(x.id)||{id:x.id,name:x.name,score:0,durationSeconds:0,played:0,isPlayer:false};c.score+=x.score;c.durationSeconds+=x.durationSeconds;c.played++;m.set(x.id,c)}));return[...m.values()]}", 'demoRows')

