one("function currentAnchor(v){const t=today();return v==='week'?weekStart(t):v==='month'?monthStart(t):t}function oldest(){return addDays(today(),-(HISTORY-1))}function clamp(a){return a>today()?today():a<oldest()?oldest():a}function period(v,a){const loc=lang()==='en'?'en-GB':'hr-HR',f=k=>new Intl.DateTimeFormat(loc,{timeZone:'UTC',day:'numeric',month:'short',year:'numeric'}).format(parse(k));if(v==='daily30')return window.KvizDaily30?.formatFullDate?.(a)||f(a);if(v==='week')return`${f(a)} – ${f(addDays(a,6))}`;if(v==='month'){const x=new Intl.DateTimeFormat(loc,{timeZone:'UTC',month:'long',year:'numeric'}).format(parse(a));return x[0].toUpperCase()+x.slice(1)}return''}",
"function currentAnchor(v){return today()}function oldest(){return START}function clamp(a){return a>today()?today():a<oldest()?oldest():a}function period(v,a){const loc=lang()==='en'?'en-GB':'hr-HR',f=k=>new Intl.DateTimeFormat(loc,{timeZone:'UTC',day:'numeric',month:'short',year:'numeric'}).format(parse(k));if(v==='daily30')return window.KvizDaily30?.formatFullDate?.(a)||f(a);if(v==='week')return`${f(weekStart(a))} – ${f(a)}`;if(v==='month'){const x=new Intl.DateTimeFormat(loc,{timeZone:'UTC',month:'long',year:'numeric'}).format(parse(a));return`${x[0].toUpperCase()+x.slice(1)} · ${lang()==='en'?'through':'do'} ${f(a)}`}return`${lang()==='en'?'As of':'Stanje na'} ${f(a)}`}", 'period')

old="function renderPreview(){const root=document.getElementById('leaderboard-preview'),list=document.getElementById('leaderboard-preview-list');if(!root||!list)return;if(!previewState.anchor)previewState.anchor=currentAnchor(previewState.view);if(previewState.view==='daily30')previewState.anchor=clamp(previewState.anchor);tabs(root,previewState.view);const pr=document.getElementById('leaderboard-preview-period');if(pr)pr.textContent=previewState.view==='all'?'':period(previewState.view,previewState.anchor);const rows=ranked(previewState.view,previewState.anchor),expanded=root.dataset.expanded==='1',shown=expanded?rows:rows.slice(0,5);list.innerHTML=shown.length?shown.map(x=>row(x,previewState.view)).join(''):`<div class=\"leaderboard-empty\">${lang()==='en'?'No results yet.':'Još nema rezultata.'}</div>`;const own=rows.find(x=>x.isPlayer),ownRoot=document.getElementById('leaderboard-preview-own');if(ownRoot){const show=!expanded&&!!(own&&own.rank>5);ownRoot.classList.toggle('visible',show);ownRoot.innerHTML=show?row(own,previewState.view):''}const link=document.getElementById('leaderboard-more-link');if(link){link.textContent=expanded?(lang()==='en'?'Show less':'Prikaži manje'):(lang()==='en'?'View full leaderboard':'Prikaži cijelu ljestvicu');link.href='#leaderboard-preview';link.onclick=e=>{e.preventDefault();root.dataset.expanded=expanded?'0':'1';renderPreview();if(!expanded)setTimeout(()=>root.scrollIntoView({behavior:'smooth',block:'start'}),0)}}}"
new="function ensurePreviewDateNav(){const label=document.getElementById('leaderboard-preview-period');if(!label)return;let wrap=document.getElementById('leaderboard-preview-date-nav');if(wrap)return;wrap=document.createElement('div');wrap.id='leaderboard-preview-date-nav';wrap.className='leaderboard-full-period';label.parentNode.insertBefore(wrap,label);const prev=document.createElement('button');prev.type='button';prev.className='leaderboard-period-nav';prev.id='leaderboard-preview-prev';prev.textContent='‹';const next=document.createElement('button');next.type='button';next.className='leaderboard-period-nav';next.id='leaderboard-preview-next';next.textContent='›';wrap.append(prev,label,next);prev.addEventListener('click',()=>shiftPreview(-1));next.addEventListener('click',()=>shiftPreview(1))}function shiftPreview(dir){previewState.anchor=clamp(addDays(previewState.anchor||today(),dir));const root=document.getElementById('leaderboard-preview');if(root)root.dataset.expanded='0';pageState.anchor=previewState.anchor;renderPreview();if(document.getElementById('leaderboard-page')?.classList.contains('open'))renderPage()}function renderPreview(){const root=document.getElementById('leaderboard-preview'),list=document.getElementById('leaderboard-preview-list');if(!root||!list)return;if(!previewState.anchor)previewState.anchor=today();previewState.anchor=clamp(previewState.anchor);tabs(root,previewState.view);ensurePreviewDateNav();const pr=document.getElementById('leaderboard-preview-period');if(pr)pr.textContent=period(previewState.view,previewState.anchor);const pp=document.getElementById('leaderboard-preview-prev'),pn=document.getElementById('leaderboard-preview-next');if(pp){pp.disabled=previewState.anchor<=oldest();pp.setAttribute('aria-label',lang()==='en'?'Previous day':'Prethodni dan')}if(pn){pn.disabled=previewState.anchor>=today();pn.setAttribute('aria-label',lang()==='en'?'Next day':'Sljedeći dan')}const rows=ranked(previewState.view,previewState.anchor),expanded=root.dataset.expanded==='1',shown=expanded?rows:rows.slice(0,5);list.innerHTML=shown.length?shown.map(x=>row(x,previewState.view)).join(''):`<div class=\"leaderboard-empty\">${lang()==='en'?'No results yet.':'Još nema rezultata.'}</div>`;const own=rows.find(x=>x.isPlayer),ownRoot=document.getElementById('leaderboard-preview-own');if(ownRoot){const show=!expanded&&!!(own&&own.rank>5);ownRoot.classList.toggle('visible',show);ownRoot.innerHTML=show?row(own,previewState.view):''}const link=document.getElementById('leaderboard-more-link');if(link){link.textContent=expanded?(lang()==='en'?'Show less':'Prikaži manje'):(lang()==='en'?'View full leaderboard':'Prikaži cijelu ljestvicu');link.href='#leaderboard-preview';link.onclick=e=>{e.preventDefault();root.dataset.expanded=expanded?'0':'1';renderPreview();if(!expanded)setTimeout(()=>root.scrollIntoView({behavior:'smooth',block:'start'}),0)}}}"
