one("function renderPage(){const root=document.getElementById('leaderboard-page'),list=document.getElementById('leaderboard-full-list');if(!root||!list)return;if(!pageState.anchor)pageState.anchor=currentAnchor(pageState.view);if(pageState.view==='daily30')pageState.anchor=clamp(pageState.anchor);tabs(root,pageState.view);document.getElementById('leaderboard-full-period')?.classList.toggle('is-all-time',pageState.view==='all');const lab=document.getElementById('leaderboard-full-period-label');if(lab)lab.textContent=period(pageState.view,pageState.anchor);const rs=ranked(pageState.view,pageState.anchor);list.innerHTML=rs.length?rs.map(x=>row(x,pageState.view)).join(''):`<div class=\"leaderboard-empty\">${lang()==='en'?'No results yet.':'Još nema rezultata.'}</div>`;const p=document.getElementById('leaderboard-period-prev'),n=document.getElementById('leaderboard-period-next');if(p)p.disabled=pageState.view==='all'||(pageState.view==='daily30'&&pageState.anchor<=oldest());if(n)n.disabled=pageState.view==='all'||pageState.anchor>=currentAnchor(pageState.view)}function shift(dir){if(pageState.view==='all')return;let x=pageState.anchor;if(pageState.view==='daily30')x=clamp(addDays(x,dir));if(pageState.view==='week')x=addDays(x,dir*7);if(pageState.view==='month')x=addMonths(x,dir);if(dir>0&&x>currentAnchor(pageState.view))x=currentAnchor(pageState.view);pageState.anchor=x;renderPage()}",
"function renderPage(){const root=document.getElementById('leaderboard-page'),list=document.getElementById('leaderboard-full-list');if(!root||!list)return;if(!pageState.anchor)pageState.anchor=previewState.anchor||today();pageState.anchor=clamp(pageState.anchor);tabs(root,pageState.view);document.getElementById('leaderboard-full-period')?.classList.remove('is-all-time');const lab=document.getElementById('leaderboard-full-period-label');if(lab)lab.textContent=period(pageState.view,pageState.anchor);const rs=ranked(pageState.view,pageState.anchor);list.innerHTML=rs.length?rs.map(x=>row(x,pageState.view)).join(''):`<div class=\"leaderboard-empty\">${lang()==='en'?'No results yet.':'Još nema rezultata.'}</div>`;const p=document.getElementById('leaderboard-period-prev'),n=document.getElementById('leaderboard-period-next');if(p){p.disabled=pageState.anchor<=oldest();p.setAttribute('aria-label',lang()==='en'?'Previous day':'Prethodni dan')}if(n){n.disabled=pageState.anchor>=today();n.setAttribute('aria-label',lang()==='en'?'Next day':'Sljedeći dan')}}function shift(dir){pageState.anchor=clamp(addDays(pageState.anchor||today(),dir));previewState.anchor=pageState.anchor;renderPage();renderPreview()}", 'renderPage')

